"""Post-processing for 1st-generation (steam) district systems generated by the GMT.

The GMT 1G district model (``DistrictEnergySystem1G.mot``) instantiates the MBL steam stack with
explicit names: ``pla`` (``Buildings.DHC.Plants.Steam.SingleBoiler``), ``dis`` (steam distribution
network) and ``bld1..bldN`` (``Buildings.DHC.Loads.Steam.BuildingTimeSeriesAtETS``). Older generated
models used an array ``bld[i]``; both naming styles are supported.

This module reads those results and computes the annual energy balance, efficiencies, fuel,
pump electricity and peaks. It also maps them onto the standard UO DES column names, so steam results
can be compared with 4G/5G results.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from pathlib import Path

import numpy as np
import pandas as pd
from buildingspy.io.outputfile import Reader

from .constants import DEFAULT_YEAR, SECONDS_PER_HOUR
from .logging_config import LoggingMixin

J_PER_GJ = 1e9
J_PER_KWH = 3.6e6
J_PER_MWH = 3.6e9
SECONDS_PER_YEAR = 365 * 24 * SECONDS_PER_HOUR

# Regex patterns (full match) for the variables in a GMT 1G steam district result. The first pattern
# with any matches wins.
STEAM_VARIABLE_PATTERNS: dict[str, list[str]] = {
    "fuel": [r"pla\.QFue_flow", r"pla\.boi\.QFueFlo"],
    "boiler_heat": [r"pla\.boi\.QWat_flow", r"pla\.boi\.preHeaFlo\.Q_flow", r"pla\.boi\.Q_flow_in\.y"],
    "delivered": [r"bld\d+\.Q_flow", r"bld\[\d+\]\.Q_flow"],
    "feedwater_pump": [r"pla\.PPum", r"pla\.pumFW\.P"],
    "condensate_pumps": [r"bld\d+\.pumCNR\.P", r"bld\[\d+\]\.pumCNR\.P"],
    "plant_steam_flow": [r"pla\.port_bSerHea\.m_flow"],
    # Optional GMT SteamLossAndMakeup component (instance losMak), present only when losses are modeled
    "loss_heat": [r"losMak\.QLos_flow"],
    "leak_flow": [r"losMak\.mLea_flow"],
    "makeup_flow": [r"losMak\.mMak_flow"],
    "discharge_flow": [r"losMak\.mDum_flow"],
}

# Hourly column names produced by SteamResults.hourly
COL_FUEL = "Fuel input rate"
COL_BOILER = "Boiler useful heat"
COL_DELIVERED = "Building load served"
COL_FW_PUMP = "Feedwater pump power"
COL_COND_PUMP = "Condensate pump power"
COL_LOSS = "Supply main heat loss"
COL_LEAK = "Steam leak flow"
COL_MAKEUP = "Make-up water flow"
COL_DISCHARGE = "Discharged condensate flow"
WATER_DENSITY = 1000.0  # kg/m3, matches losMak.rhoWat


@dataclass(frozen=True)
class SteamFuel:
    """Fuel properties. Defaults are the MBL ``Buildings.Fluid.Data.Fuels.NaturalGasLowerHeatingValue``
    record used by ``Buildings.DHC.Plants.Steam.SingleBoiler``.

    Note that the MBL density (0.84 kg/m3) is higher than typical pipeline gas (~0.72-0.78 kg/m3), so
    report gas as energy first and volume on a stated basis.
    """

    lower_heating_value: float = 50e6  # J/kg
    density: float = 0.84  # kg/m3
    co2_per_kg: float = 2.23  # kg CO2 / kg fuel


def _natural_key(name: str) -> list:
    return [int(t) if t.isdigit() else t for t in re.split(r"(\d+)", name)]


@dataclass
class SteamResults(LoggingMixin):
    """Results of a GMT-generated 1G steam district simulation.

    Example::

        res = SteamResults(path / "oneg_steam.Districts.DistrictEnergySystem_res.mat")
        res.annual_summary()  # dict of annual metrics
        res.hourly()  # hourly DataFrame (W)
        res.monthly()  # monthly DataFrame (GJ)

    :param mat_filename: path to the ``_res.mat`` file. Optional if ``reader`` is passed.
    :param reader: an object with ``varNames()`` and ``values(name)`` (e.g., buildingspy ``Reader``).
    :param year: calendar year used for the datetime index.
    :param start_time: simulation start time, in seconds.
    :param stop_time: simulation stop time, in seconds. Defaults to the last time in the result.
    :param exclude_startup_seconds: initial period excluded from totals and peaks (startup transient).
    :param fuel: fuel properties.
    """

    mat_filename: Path | None = None
    reader: object | None = None
    year: int = DEFAULT_YEAR
    start_time: float = 0.0
    stop_time: float | None = None
    exclude_startup_seconds: float = SECONDS_PER_HOUR
    fuel: SteamFuel = field(default_factory=SteamFuel)

    def __post_init__(self) -> None:
        if self.reader is None:
            if self.mat_filename is None:
                raise ValueError("Either mat_filename or reader must be provided")
            if not Path(self.mat_filename).exists():
                raise FileNotFoundError(f"Steam result not found: {self.mat_filename}")
            self.reader = Reader(str(self.mat_filename), "dymola")
        self.variables = self.find_variables()
        missing = [k for k in ("fuel", "delivered") if not self.variables[k]]
        if missing:
            raise KeyError(f"Could not find steam variables {missing}. Is this a GMT 1G steam district result?")
        self._series_cache: dict[str, pd.Series] = {}
        if self.stop_time is None:
            self.stop_time = float(self._series(self.variables["fuel"][0]).index.max())
        self.logger.debug(f"Steam variables found: {self.variables}")

    # ------------------------------------------------------------------ variable access
    def find_variables(self) -> dict[str, list[str]]:
        """Find the result variables for each quantity using STEAM_VARIABLE_PATTERNS."""
        names = self.reader.varNames()
        found = {}
        for key, patterns in STEAM_VARIABLE_PATTERNS.items():
            found[key] = []
            for pattern in patterns:
                hits = sorted((n for n in names if re.fullmatch(pattern, n)), key=_natural_key)
                if hits:
                    found[key] = hits
                    break
        return found

    @property
    def number_of_buildings(self) -> int:
        return len(self.variables["delivered"])

    def _series(self, var: str) -> pd.Series:
        if var not in self._series_cache:
            t, y = self.reader.values(var)
            s = pd.Series(np.asarray(y, dtype=float), index=np.asarray(t, dtype=float))
            # Modelica results repeat time stamps at events; keep the last value
            self._series_cache[var] = s[~s.index.duplicated(keep="last")]
        return self._series_cache[var]

    def _sum_series(self, variables: list[str]) -> pd.Series | None:
        if not variables:
            return None
        base = self._series(variables[0])
        total = base.copy()
        for v in variables[1:]:
            s = self._series(v)
            total = total + np.interp(base.index.to_numpy(), s.index.to_numpy(), s.to_numpy())
        return total

    def raw_series(self) -> dict[str, pd.Series | None]:
        """Native-resolution time series (W) for each quantity, indexed by seconds."""
        v = self.variables
        return {
            COL_FUEL: self._series(v["fuel"][0]),
            COL_BOILER: self._series(v["boiler_heat"][0]) if v["boiler_heat"] else None,
            COL_DELIVERED: self._sum_series(v["delivered"]),
            COL_FW_PUMP: self._series(v["feedwater_pump"][0]) if v["feedwater_pump"] else None,
            COL_COND_PUMP: self._sum_series(v["condensate_pumps"]),
            COL_LOSS: self._series(v["loss_heat"][0]) if v["loss_heat"] else None,
            COL_LEAK: self._series(v["leak_flow"][0]) if v["leak_flow"] else None,
            COL_MAKEUP: self._series(v["makeup_flow"][0]) if v["makeup_flow"] else None,
            COL_DISCHARGE: self._series(v["discharge_flow"][0]) if v["discharge_flow"] else None,
        }

    @property
    def has_losses(self) -> bool:
        """True when the result includes the GMT SteamLossAndMakeup component (losMak)."""
        return bool(self.variables["makeup_flow"])

    def parameter(self, name: str) -> float:
        """Value of a (time-invariant) model parameter, e.g. 'mDis_flow_nominal'."""
        return float(self.reader.values(name)[1][-1])

    def annual_plant_steam_mass(self) -> float:
        """Steam mass leaving the plant (kg), from t_min to stop_time."""
        if not self.variables["plant_steam_flow"]:
            raise KeyError("Plant steam flow (pla.port_bSerHea.m_flow) not found in the result")
        # port_b flow is negative when leaving the plant
        return abs(self._integrate(self._series(self.variables["plant_steam_flow"][0])))

    # ------------------------------------------------------------------ aggregations
    def _t_min(self) -> float:
        return self.start_time + self.exclude_startup_seconds

    def _integrate(self, s: pd.Series | None) -> float:
        """Energy (J) from t_min to stop_time, trapezoidal on native resolution."""
        if s is None:
            return float("nan")
        s = s[(s.index >= self._t_min()) & (s.index <= self.stop_time)]
        if len(s) < 2:
            return 0.0
        return float(np.trapezoid(s.to_numpy(), s.index.to_numpy()))

    def _peak(self, s: pd.Series | None) -> float:
        if s is None:
            return float("nan")
        s = s[(s.index >= self._t_min()) & (s.index <= self.stop_time)]
        return float(s.max()) if len(s) else float("nan")

    def hourly(self) -> pd.DataFrame:
        """Hourly instantaneous values (W), with a datetime index for ``year``."""
        grid = np.arange(self.start_time, self.stop_time + 1, SECONDS_PER_HOUR, dtype=float)
        data = {col: np.interp(grid, s.index.to_numpy(), s.to_numpy()) for col, s in self.raw_series().items() if s is not None}
        df = pd.DataFrame(data, index=grid)
        df.index = pd.Timestamp(f"{self.year}-01-01") + pd.to_timedelta(df.index, unit="s")
        df.index.name = "datetime"
        return df

    def monthly(self) -> pd.DataFrame:
        """Monthly energy (GJ) and water (leak in t, make-up and discharge in m3), excluding the startup period.

        Integrated on the native result resolution, so the months sum to the annual totals.
        """
        t0 = pd.Timestamp(f"{self.year}-01-01")
        t_lo, t_hi = self._t_min(), float(self.stop_time)
        month_starts = pd.date_range(t0, periods=13, freq="MS")
        edges = np.clip((month_starts - t0).total_seconds().to_numpy(), t_lo, t_hi)
        data = {}
        mass_cols = {COL_LEAK: 1000.0, COL_MAKEUP: WATER_DENSITY, COL_DISCHARGE: WATER_DENSITY}
        for col, series in self.raw_series().items():
            if series is None:
                continue
            s = series[(series.index >= t_lo) & (series.index <= t_hi)]
            t, y = s.index.to_numpy(), s.to_numpy()
            if len(t) < 2:
                data[col] = np.zeros(12)
                continue
            # cumulative trapezoid, then the energy between month edges
            cum = np.concatenate([[0.0], np.cumsum(np.diff(t) * (y[1:] + y[:-1]) / 2)])
            # energy columns in GJ; leak in t, make-up and discharge in m3
            data[col] = np.diff(np.interp(edges, t, cum)) / mass_cols.get(col, J_PER_GJ)
        df = pd.DataFrame(data, index=month_starts[:12])
        df.index.name = "month"
        return df.loc[(df != 0).any(axis=1) | (df.index < t0 + pd.Timedelta(seconds=t_hi))]

    def annual_summary(self) -> dict[str, float]:
        """Annual metrics. Keys include units."""
        r = self.raw_series()
        e_fuel = self._integrate(r[COL_FUEL])
        e_boiler = self._integrate(r[COL_BOILER])
        e_del = self._integrate(r[COL_DELIVERED])
        e_fw = self._integrate(r[COL_FW_PUMP])
        e_cond = self._integrate(r[COL_COND_PUMP])
        fuel_kg = e_fuel / self.fuel.lower_heating_value
        return {
            "Total energy in (fuel, LHV) [GJ]": e_fuel / J_PER_GJ,
            "Boiler useful heat [GJ]": e_boiler / J_PER_GJ,
            "Delivered to buildings [GJ]": e_del / J_PER_GJ,
            "Combustion loss [GJ]": (e_fuel - e_boiler) / J_PER_GJ,
            "Dist. + storage loss [GJ]": (e_boiler - e_del) / J_PER_GJ,
            f"Natural gas [m3, d={self.fuel.density}]": fuel_kg / self.fuel.density,
            "Natural gas [t]": fuel_kg / 1000,
            "CO2 [t]": fuel_kg * self.fuel.co2_per_kg / 1000,
            "Boiler efficiency [%]": 100 * e_boiler / e_fuel if e_fuel else float("nan"),
            "System efficiency [%]": 100 * e_del / e_fuel if e_fuel else float("nan"),
            "Feedwater pump electricity [kWh]": e_fw / J_PER_KWH,
            "Condensate pump electricity [kWh]": e_cond / J_PER_KWH,
            "Peak fuel rate [kW]": self._peak(r[COL_FUEL]) / 1e3,
            "Peak boiler heat [kW]": self._peak(r[COL_BOILER]) / 1e3,
            "Peak delivered heat [kW]": self._peak(r[COL_DELIVERED]) / 1e3,
            "Number of buildings": self.number_of_buildings,
            "Supply main heat loss [GJ]": self._integrate(r[COL_LOSS]) / J_PER_GJ if self.has_losses else 0.0,
            "Steam leaked [t]": self._integrate(r[COL_LEAK]) / 1000 if self.has_losses else 0.0,
            "Make-up water [m3]": self._integrate(r[COL_MAKEUP]) / WATER_DENSITY if self.has_losses else 0.0,
            "Discharged condensate [m3]": self._integrate(r[COL_DISCHARGE]) / WATER_DENSITY if self.has_losses else 0.0,
        }

    def to_uo_des_columns(self) -> pd.DataFrame:
        """Hourly power (W) using the standard UO DES column names, for comparison with 4G/5G results.

        Steam plant fuel maps to 'Total Heating Natural Gas Plant' / 'Total DES Natural Gas', the feedwater
        pump to 'Distribution Pump Electricity', the condensate pumps to 'ETS Pump Electricity Total', and the
        delivered heat to 'ETS Thermal Heating Total'. Building electricity is not included; add it from the
        URBANopt (Non-Connected) results for a site total.
        """
        h = self.hourly()
        zero = pd.Series(0.0, index=h.index)
        fw = h.get(COL_FW_PUMP, zero)
        cond = h.get(COL_COND_PUMP, zero)
        return pd.DataFrame(
            {
                "Total Heating Natural Gas Plant": h[COL_FUEL],
                "Total DES Natural Gas": h[COL_FUEL],
                "Distribution Pump Electricity": fw,
                "ETS Pump Electricity Total": cond,
                "Total DES Electricity": fw + cond,
                "ETS Thermal Heating Total": h[COL_DELIVERED],
            },
            index=h.index,
        )

    def save(self, output_dir: Path, prefix: str = "steam") -> list[Path]:
        """Write summary, hourly and monthly CSVs to ``output_dir``. Only new or own files are written there."""
        output_dir = Path(output_dir)
        output_dir.mkdir(parents=True, exist_ok=True)
        paths = [output_dir / f"{prefix}_summary.csv", output_dir / f"{prefix}_hourly.csv", output_dir / f"{prefix}_monthly.csv"]
        pd.Series(self.annual_summary(), name="value").to_csv(paths[0])
        self.hourly().to_csv(paths[1])
        self.monthly().to_csv(paths[2])
        return paths


def compare_to_targets(summary: dict[str, float], targets: dict[str, tuple[float, float]]) -> pd.DataFrame:
    """Compare annual metrics against reference values.

    :param summary: output of ``SteamResults.annual_summary()``
    :param targets: {metric: (reference value, relative tolerance)}, e.g. {"Peak fuel rate [kW]": (4209, 0.05)}
    :return: DataFrame with Original, Re-run, Diff %, Tolerance %, Pass
    """
    rows = []
    for metric, (ref, tol) in targets.items():
        val = summary[metric]
        diff = 100 * (val - ref) / ref
        rows.append(
            {"Metric": metric, "Original": ref, "Re-run": val, "Diff %": diff, "Tolerance %": 100 * tol, "Pass": abs(diff) <= 100 * tol},
        )
    return pd.DataFrame(rows).set_index("Metric")


def steam_loss_parameters(
    baseline: SteamResults,
    leak_share: float,
    heat_loss_share: float,
    condensate_return_fraction: float = 1.0,
    makeup_water_temperature: float = 12.0,
) -> dict[str, float]:
    """Convert annual loss shares (as reported in the literature) into GMT steam loss parameters.

    GMT models the steam leak and the supply-main heat loss as constant fractions of the district nominal
    steam mass flow (``mDis_flow_nominal``) and heat flow (``QDis_flow_nominal``). The annual share that a
    constant loss represents depends on the district load factor, so it is calibrated from a lossless run
    of the same district.

    :param baseline: results of the lossless (S0) run of the same district
    :param leak_share: annual leaked steam as a fraction of the steam leaving the plant (e.g., 0.10)
    :param heat_loss_share: annual supply-main heat loss as a fraction of the heat leaving the plant (e.g., 0.08)
    :param condensate_return_fraction: fraction of condensate returned to the plant (1 = full, 0 = none)
    :param makeup_water_temperature: make-up water temperature, degC
    :return: dict to merge into ``district_system.first_generation.central_steam_plant_parameters``
    """
    for name, value in [
        ("leak_share", leak_share),
        ("heat_loss_share", heat_loss_share),
        ("condensate_return_fraction", condensate_return_fraction),
    ]:
        if not 0.0 <= value <= 1.0:
            raise ValueError(f"{name} must be between 0 and 1, got {value}")
    if baseline.has_losses:
        raise ValueError("The baseline must be a lossless run (no losMak component)")

    seconds = float(baseline.stop_time) - baseline._t_min()
    m_nominal = baseline.parameter("mDis_flow_nominal")
    q_nominal = baseline.parameter("QDis_flow_nominal")
    steam_mass = baseline.annual_plant_steam_mass()
    boiler_heat = baseline.annual_summary()["Boiler useful heat [GJ]"] * J_PER_GJ

    return {
        "steam_leak_fraction": leak_share * steam_mass / (m_nominal * seconds),
        "distribution_heat_loss_fraction": heat_loss_share * boiler_heat / (q_nominal * seconds),
        "condensate_return_fraction": condensate_return_fraction,
        "makeup_water_temperature": makeup_water_temperature,
    }
